std::istringstream in("(?\n");
std::ostringstream out;
std::streambuf* cout_old = std::cout.rdbuf(out.rdbuf());
solve(in, out);
std::cout.rdbuf(cout_old);
CHECK_EQ(out.str(), std::string("0\n"));

std::istringstream in(")(\n");
std::ostringstream out;
std::streambuf* cout_old = std::cout.rdbuf(out.rdbuf());
solve(in, out);
std::cout.rdbuf(cout_old);
CHECK_EQ(out.str(), std::string("2\n"));

